<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import Modal from '@/Components/Modal.vue';
import ValidationSummary from '@/Components/ValidationSummary.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, reactive, ref } from 'vue';
const props = defineProps<{customers:any[]; packages:any[]; filters:any}>();
const filters = reactive({...props.filters}); const showCreate = ref(false); const showSecondLogin = ref(false);
const form = useForm({name:'', phone:'', guest_capacity:'', primary_name:'', primary_email:'', primary_password:'', secondary_name:'', secondary_email:'', secondary_password:''});
const packagePreview = computed(() => props.packages.filter((item:any) => Number(form.guest_capacity) >= item.minimum_guests && Number(form.guest_capacity) <= item.maximum_guests));
const apply = () => router.get(route('admin.customers.index'), filters, {preserveState:true,replace:true}); const reset = () => { filters.search=''; apply(); };
const closeCreate = () => { showCreate.value=false; form.clearErrors(); }; const removeSecondLogin = () => { showSecondLogin.value=false; form.secondary_name=''; form.secondary_email=''; form.secondary_password=''; };
const submit = () => form.post(route('admin.clients.store'), { onSuccess: () => { form.reset(); removeSecondLogin(); showCreate.value=false; } });
</script>
<template><Head title="Clients"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between gap-4"><h2 class="text-xl font-semibold">Clients</h2><button @click="showCreate=true" class="rounded bg-indigo-600 px-4 py-2 text-sm font-medium text-white">+ Add Client</button></div></template><div class="mx-auto max-w-7xl space-y-5 p-6"><form @submit.prevent="apply" class="flex flex-wrap gap-2"><input v-model="filters.search" placeholder="Search name, email, phone" class="rounded border-gray-300"><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="text-gray-600">Reset</button></form><div class="overflow-x-auto bg-white shadow"><table class="min-w-full divide-y divide-gray-200 text-sm"><thead class="bg-gray-50 text-left text-gray-600"><tr><th class="px-4 py-3">Client</th><th class="px-4 py-3">Primary Login</th><th class="px-4 py-3">Second Login</th><th class="px-4 py-3">Event</th><th class="px-4 py-3">Guest Capacity</th><th class="px-4 py-3">Invitation Status</th><th class="px-4 py-3">Payment Status</th><th class="px-4 py-3"></th></tr></thead><tbody class="divide-y divide-gray-200"><tr v-for="customer in customers" :key="customer.id"><td class="px-4 py-3 font-medium text-gray-900">{{ customer.name }}</td><td class="px-4 py-3"><template v-if="customer.primary_login"><span class="block">{{ customer.primary_login.name }}</span><span class="text-gray-500">{{ customer.primary_login.email }}</span></template><span v-else>—</span></td><td class="px-4 py-3"><template v-if="customer.second_login"><span class="block">{{ customer.second_login.name }}</span><span class="text-gray-500">{{ customer.second_login.email }}</span></template><span v-else>—</span></td><template v-if="customer.event"><td class="px-4 py-3">{{ customer.event.title || 'Invitation setup not completed' }}</td><td class="px-4 py-3">{{ customer.event.guest_capacity ? `${customer.event.guest_capacity} guests` : '—' }}</td><td class="px-4 py-3">{{ customer.event.invitation_status }}</td><td class="px-4 py-3">{{ customer.event.payment_status }}</td></template><template v-else><td class="px-4 py-3" colspan="4">{{ customer.event_count ? `${customer.event_count} Events` : 'No Events' }}</td></template><td class="px-4 py-3 text-right"><Link :href="route('admin.customers.show',customer.id)" class="text-indigo-600">View Client</Link></td></tr><tr v-if="!customers.length"><td colspan="8" class="px-4 py-6 text-gray-600">No Clients match your search.</td></tr></tbody></table></div></div><Modal :show="showCreate" max-width="2xl" @close="closeCreate"><form @submit.prevent="submit" class="space-y-5 p-6"><div class="flex items-start justify-between gap-4"><div><h3 class="text-lg font-semibold">Add Client</h3><p class="mt-1 text-sm text-gray-600">Create the Client login and Event setup shell. The Client completes invitation details later.</p></div><button type="button" @click="closeCreate" class="text-xl text-gray-500" aria-label="Close">×</button></div><section class="space-y-3"><h4 class="font-medium">Client</h4><div class="grid gap-3 sm:grid-cols-2"><label>Client name<input v-model="form.name" required class="mt-1 w-full rounded border-gray-300"/></label><label>Phone <span class="text-gray-500">(optional)</span><input v-model="form.phone" class="mt-1 w-full rounded border-gray-300"/></label><label>Guest capacity<input v-model="form.guest_capacity" type="number" min="1" required class="mt-1 w-full rounded border-gray-300"/><span v-if="packagePreview.length === 1" class="mt-1 block text-sm text-gray-600">Package: {{ packagePreview[0].name }} · Price: {{ packagePreview[0].price ?? 'not set' }}</span><span v-else-if="form.guest_capacity" class="mt-1 block text-sm text-amber-700">{{ packagePreview.length ? 'Package configuration is ambiguous.' : 'No active Package covers this capacity.' }}</span></label></div></section><section class="space-y-3 border-t pt-4"><h4 class="font-medium">Primary login <span class="text-red-600">required</span></h4><div class="grid gap-3 sm:grid-cols-3"><label>Name<input v-model="form.primary_name" required class="mt-1 w-full rounded border-gray-300"/></label><label>Login email<input v-model="form.primary_email" type="email" required class="mt-1 w-full rounded border-gray-300"/></label><label>Temporary password<input v-model="form.primary_password" type="password" required class="mt-1 w-full rounded border-gray-300"/></label></div></section><section class="border-t pt-4"><button v-if="!showSecondLogin" type="button" @click="showSecondLogin=true" class="text-sm font-medium text-indigo-600">+ Add second login</button><template v-else><div class="flex items-center justify-between"><h4 class="font-medium">Second login <span class="text-gray-500">(optional)</span></h4><button type="button" @click="removeSecondLogin" class="text-sm text-red-700">Remove</button></div><div class="mt-3 grid gap-3 sm:grid-cols-3"><label>Name<input v-model="form.secondary_name" class="mt-1 w-full rounded border-gray-300"/></label><label>Login email<input v-model="form.secondary_email" type="email" class="mt-1 w-full rounded border-gray-300"/></label><label>Temporary password<input v-model="form.secondary_password" type="password" class="mt-1 w-full rounded border-gray-300"/></label></div></template></section><ValidationSummary :errors="form.errors"/><div class="flex justify-end gap-3 border-t pt-4"><button type="button" @click="closeCreate" class="rounded border px-4 py-2">Cancel</button><button class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-60" :disabled="form.processing">Create Client</button></div></form></Modal></AuthenticatedLayout></template>
